Inductive Nat : Type :=
  | Z : Nat
  | S : Nat -> Nat.

Fixpoint add (a b : Nat) : Nat :=
  match a with
  | Z => b
  | S a => S (add a b)
  end.

Fixpoint mul (a b : Nat) : Nat :=
  match a with
  | Z => Z
  | S a => add b (mul a b)
  end.

Definition dbl (x : Nat) : Nat := add x x.

Inductive L : Type :=
  | Ln : L
  | Lc : Nat -> L -> L.

Fixpoint cat (xs ys : L) : L :=
  match xs with
  | Ln => ys
  | Lc h t => Lc h (cat t ys)
  end.

Fixpoint fa0 (x : Nat) : Nat :=
  match x with
  | Z => dbl (S Z)
  | S q => S (fa0 q)
  end.

Definition ga0 (x y : Nat) : Nat := add (fa0 x) (dbl y).

Fixpoint fb1 (xs : L) : L :=
  match xs with
  | Ln => Ln
  | Lc h t => Lc (fa0 h) (fb1 t)
  end.

Fixpoint fc2 (xs : L) : Nat :=
  match xs with
  | Ln => Z
  | Lc h t => add (fa0 h) (fc2 t)
  end.

Definition gc2 (x : Nat) : Nat := fc2 (Lc x (Lc (fa0 x) Ln)).

Fixpoint fa3 (x : Nat) : Nat :=
  match x with
  | Z => gc2 (S Z)
  | S q => S (fa3 q)
  end.

Definition ga3 (x y : Nat) : Nat := add (fa3 x) (gc2 y).

